// Get canvas and context
const canvas = document.querySelector("#canvas");
const ctx = canvas.getContext("2d");

// Set initial canvas size
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Wave settings
const WAVES = [];
const WAVE_COUNT = 12;
const PERSPECTIVE = 300; // Depth effect factor
const MAX_CIRCLE_RADIUS = 12; // Maximum radius of particles
const POINT_SPACING = 20; // Distance between particles in a wave

// Mouse position
let mousePosX = canvas.width / 2;
let mousePosY = canvas.height / 2;

// Initialize waves with random properties
for (let i = 0; i < WAVE_COUNT; i++) {
  WAVES.push({
    baseY: canvas.height / 2 - 200 + Math.random() * 400, // Base Y position
    waveLength: 0.002 + Math.random() * 0.008, // Wave horizontal stretch
    amplitude: 50 + Math.random() * 0.015, // Wave height
    phase: Math.random() * PERSPECTIVE, // Wave starting phase
    posY: 0, // Current Y position (updated later)
    radiusOffset: Math.random() * MAX_CIRCLE_RADIUS, // Random size variation
    depthZ: Math.random() * MAX_CIRCLE_RADIUS, // Z-depth for perspective
    frequency: 0.005 + Math.random() * 0.015, // Speed of phase change
  });
  WAVES[i].posY = WAVES[i].baseY; // Set initial Y to baseY
}

let time = 0; // Animation time counter

// Update mouse position on movement
canvas.addEventListener("mousemove", (event) => {
  mousePosX = event.clientX;
  mousePosY = event.clientY;
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  // Semi-transparent white background for fade effect
  ctx.fillStyle = `rgba(255, 255, 255, 0.1)`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  WAVES.forEach((wave, index) => {
    ctx.lineWidth = 2;
    const scale = PERSPECTIVE / (PERSPECTIVE + wave.depthZ); // Perspective scaling
    wave.posY = wave.baseY + Math.sin(time * 0.001 + wave.depthZ) * 20; // Vertical oscillation
    const scaledY = wave.posY * scale + (canvas.height / 2) * (1 - scale); // Adjusted Y with perspective

    // Draw particles along the wave
    for (let x = 0; x < canvas.width; x += POINT_SPACING) {
      const deltaX = mousePosX - x;
      const waveY =
        scaledY +
        Math.sin(x * wave.waveLength + wave.phase) *
          wave.amplitude *
          Math.sin(wave.phase) *
          scale;
      const deltaY = mousePosY - waveY;
      const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY); // Distance from mouse

      // Pulsing radius effect
      const circleRadius =
        MAX_CIRCLE_RADIUS -
        Math.abs(Math.sin(time * 0.01 + index)) * MAX_CIRCLE_RADIUS;

      // Mouse interaction: push particles away
      const newX = x + (deltaX / distance) * Math.min(50, 1000 / distance);
      const newY = waveY + (deltaY / distance) * Math.min(50, 1000 / distance);

      // Draw particle
      ctx.beginPath();
      ctx.arc(newX, newY, circleRadius + wave.radiusOffset, 0, 2 * Math.PI);
      ctx.fillStyle = `rgba(0, 150, 255, 1)`; // Bright blue color
      ctx.fill();
    }

    wave.phase += wave.frequency; // Increment phase for wave motion
  });

  time++; // Advance time for animation
}

// Start animation
animate();

// Resize handler to adjust canvas and wave positions
window.addEventListener("resize", () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  WAVES.forEach((wave) => {
    wave.baseY = canvas.height / 2 - 200 + Math.random() * 400; // Recalculate base Y
    wave.posY = wave.baseY; // Reset current Y
  });
});
